/* ============ REVISION 2, PART 2: first programs (1.1, 1.4) and the parts lesson (1.5) ============ */

/* ---------- 1.1 Blink in three steps: instructions, then code, then change a number ---------- */
INTERACTIVES.blinkIntro = function(el){
  const pin = pinK(getBoard(), "LED_PIN"); let tab = 0, seq = [], timer = null, idx = -1, ms = 500, onMs = 500;
  const CARD = {on:["LED ON", "digitalWrite(LED_PIN, HIGH);"], off:["LED OFF", "digitalWrite(LED_PIN, LOW);"], wait:["WAIT ½ second", "delay(500);"]};
  const analyze = s => { if (!s.length) return "Add some cards first."; let led = false, t = 0; const on = [], off = []; let cur = 0, state = null;
    for (let pass = 0; pass < 2; pass++) for (const k of s){ if (k === "wait") cur += 500; else { if (state !== null) (state ? on : off).push(cur); cur = 0; state = k === "on"; } }
    const hasOn = s.includes("on"), hasOff = s.includes("off");
    if (!hasOn) return "The LED never turns ON, so nothing happens. A program does <b>exactly</b> what it says, nothing more.";
    if (!hasOff) return "The LED turns on and <b>stays on</b>. You never told it to turn off.";
    const lastOn = Math.max(...on, 0), lastOff = Math.max(...off, 0);
    if (!on.some(x => x > 0) || !off.some(x => x > 0)) return "The LED switches on and off, but without a <b>WAIT</b> in between it happens thousands of times a second. Your eyes see it as steady, dim light. <b>Waiting is what makes a blink visible.</b>";
    return `<b>Blinking!</b> ON for about ${(Math.max(...on) / 1000).toFixed(1)} s, OFF for about ${(Math.max(...off) / 1000).toFixed(1)} s. After the last card the board goes back to the first one: that is what <code>loop()</code> does.`; };
  const render = () => {
    const st = tab === 0 ? `<p>A program is a <b>list of instructions</b>. The board follows them <b>one at a time, from top to bottom</b>, then starts again from the top, forever. Your job: make the LED blink (on, wait, off, wait) by tapping the cards below to build the list.</p>
      <div class="cardrow">${Object.keys(CARD).map(k => `<button type="button" data-k="${k}">+ ${CARD[k][0]}</button>`).join("")}</div>
      <p class="explain"><b>Your program</b> (tap a card in it to remove it). The board repeats this list forever:</p><div class="seqbox bsQ">${seq.map((k, i) => `<span class="tk ${i === idx ? "cur" : ""}" data-i="${i}">${CARD[k][0]}</span>`).join("") || '<span class="explain">empty</span>'}</div>
      <div class="controls"><button class="btn primary bsRun" type="button">${timer ? "Stop" : "Run"}</button><button class="btn bsClr" type="button">Clear</button><button class="btn bsShow" type="button">Show me the answer</button></div>
      <div class="ix-grid2"><div class="big-led ${tok.on ? "on" : ""}" style="margin:8px auto" role="img" aria-label="LED ${tok.on ? "on" : "off"}"></div><div class="ix-out bsOut" aria-live="polite">${esc("")}${analyze(seq)}</div></div>
      <p class="explain">In a real board, ON and OFF take a few millionths of a second. The animation pauses on each card so you can follow along; only the WAIT cards take real time.</p>`
     : tab === 1 ? `<p>Now the <b>same program written for the Arduino</b>. Every card became one line of C++. Tap a numbered line to see what it means.</p>
      <table class="t"><tr><th>Your card</th><th>becomes this line of code</th></tr>${["on", "wait", "off", "wait"].map(k => `<tr><td><b>${CARD[k][0]}</b></td><td><code>${CARD[k][1]}</code></td></tr>`).join("")}<tr><td><b>(repeat forever)</b></td><td>everything inside <code>void loop() { … }</code></td></tr></table>
      ${anat("Blink, line by line", [[`const int LED_PIN = ${pin};`, "Give the pin number a name. <code>const</code> means it never changes; <code>int</code> means a whole number. Now the rest of the code can say <code>LED_PIN</code> instead of " + pin + "."], ["", ""],
        ["void setup() {", "<code>setup()</code> runs <b>once</b>, when the board starts. Use it for one-time preparation."], ["  pinMode(LED_PIN, OUTPUT);", "Tell the board that this pin sends signals <b>out</b> (to the LED), instead of listening for signals coming in."], ["}", ""], ["", ""],
        ["void loop() {", "<code>loop()</code> runs <b>again and again, forever</b>. This is the “repeat forever” box from the cards."], ["  digitalWrite(LED_PIN, HIGH);", "HIGH means “send power out of the pin”: the LED turns <b>ON</b>."], ["  delay(500);", "Do nothing for 500 milliseconds (half a second), so you can see the LED on. 1000 ms = 1 second."],
        ["  digitalWrite(LED_PIN, LOW);", "LOW means “no power”: the LED turns <b>OFF</b>."], ["  delay(500);", "Wait again. Without this wait the loop would jump back and turn the LED on straight away: you would never see it off."], ["}", "The end of <code>loop()</code>. The board jumps back to the first line inside it."]])}
      <p class="explain">Small rules: every instruction ends with a semicolon <code>;</code>. Curly braces <code>{ }</code> wrap a block. Capital letters matter: <code>pinMode</code> is not <code>pinmode</code>. Text after <code>//</code> is a comment for humans; the board ignores it.</p>`
     : `<p>Now change the numbers and <b>predict</b> what you will see before you look. The code updates as you move the sliders.</p>
      <div class="controls"><label>ON time (ms) <input type="range" class="bsOn" min="20" max="1500" step="10" value="${onMs}"></label><span class="rangeval bsOnV">${onMs} ms</span></div>
      <div class="controls"><label>OFF time (ms) <input type="range" class="bsOff" min="20" max="1500" step="10" value="${ms}"></label><span class="rangeval bsOffV">${ms} ms</span></div>
      <div class="ix-grid2"><div><div class="big-led bsL" style="margin:8px auto"></div><p class="explain" style="text-align:center">your LED</p></div>
       <div><div class="codebox"><pre class="code"><code>digitalWrite(LED_PIN, HIGH);\ndelay(<b class="bsC1">${onMs}</b>);\ndigitalWrite(LED_PIN, LOW);\ndelay(<b class="bsC2">${ms}</b>);</code></pre></div><div class="ix-out bsOut2"></div></div></div>
      <p class="explain">Try: ON 100 ms / OFF 900 ms (a quick flash, like a heartbeat monitor). Both 20 ms: why does the LED look steady?</p>`;
    el.innerHTML = bench("Blink in three steps", `<div class="seg seg-sm bsT">${["1. Give instructions", "2. See the code", "3. Change the numbers"].map((t, i) => `<button type="button" data-t="${i}" aria-selected="${i === tab}">${t}</button>`).join("")}</div>${st}`);
    el.querySelectorAll(".bsT button").forEach(b => b.onclick = () => { stop(); tab = +b.dataset.t; render(); if (tab === 1) markAct("blinkIntro", "code"); });
    if (tab === 0){ el.querySelectorAll(".cardrow button").forEach(b => b.onclick = () => { stop(); seq.push(b.dataset.k); render(); });
      el.querySelectorAll(".bsQ .tk").forEach(t => t.onclick = () => { stop(); seq.splice(+t.dataset.i, 1); render(); });
      $(".bsRun", el).onclick = () => timer ? (stop(), render()) : run(); $(".bsClr", el).onclick = () => { stop(); seq = []; render(); };
      $(".bsShow", el).onclick = () => { stop(); seq = ["on", "wait", "off", "wait"]; render(); }; }
    if (tab === 2){ const upd = () => { onMs = +$(".bsOn", el).value; ms = +$(".bsOff", el).value; $(".bsOnV", el).textContent = onMs + " ms"; $(".bsOffV", el).textContent = ms + " ms"; $(".bsC1", el).textContent = onMs; $(".bsC2", el).textContent = ms;
        const f = 1000 / (onMs + ms); $(".bsOut2", el).innerHTML = `One blink takes ${onMs + ms} ms, so about <b>${f.toFixed(1)} blinks per second</b>. ${onMs + ms < 40 ? "Too fast for your eyes: it looks steady and dim." : f > 8 ? "A fast flicker." : f > 2 ? "A lively blink." : "A calm blink."}`; markAct("blinkIntro", "changed"); };
      el.querySelectorAll("input").forEach(x => x.oninput = upd); upd(); let on = false, t0 = performance.now(); const led = $(".bsL", el);
      const f = now => { if (!alive(el) || tab !== 2) return; const cyc = onMs + ms, ph = (now - t0) % cyc; const o = ph < onMs; if (o !== on){ on = o; led.classList.toggle("on", on); } requestAnimationFrame(f); }; if (!reduceMotion()) requestAnimationFrame(f); else led.classList.add("on"); }
  };
  const tok = {on:false};
  const stop = () => { if (timer){ clearTimeout(timer); timer = null; } idx = -1; tok.on = false; };
  const run = () => { if (tab !== 0) return; if (!seq.length){ $(".bsOut", el).innerHTML = "Add some cards first."; return; } idx = -1;
    const tick = () => { if (!alive(el) || tab !== 0){ stop(); return; } idx = (idx + 1) % seq.length; const k = seq[idx]; if (k === "on") tok.on = true; if (k === "off") tok.on = false;
      el.querySelectorAll(".bsQ .tk").forEach((t, i) => t.classList.toggle("cur", i === idx)); $(".big-led", el).classList.toggle("on", tok.on);
      timer = setTimeout(tick, k === "wait" ? 500 : 220); };
    timer = true; { const rb = $(".bsRun", el); if (rb) rb.textContent = "Stop"; } markAct("blinkIntro", "run"); tick(); };
  render();
};

/* ---------- generic step-through engine: code on the left, variables and output on the right ---------- */
function walkEngine(el, o){
  let i = 0; const F = () => o.frames();
  const draw = () => { const fr = F(), f = fr[Math.min(i, fr.length - 1)], prev = fr[Math.max(0, i - 1)] || {vars:{}};
    $(".wkC", el).innerHTML = (typeof o.lines === "function" ? o.lines() : o.lines).map((l, k) => `<div class="codeline ${f.ln === k ? "hl" : ""}">${esc(l) || " "}</div>`).join("");
    $(".wkV", el).innerHTML = Object.keys(f.vars || {}).map(k => `<div class="vb ${prev.vars && prev.vars[k] !== f.vars[k] ? "chg" : ""}"><small>${esc(k)}</small><b>${esc(f.vars[k])}</b></div>`).join("") || '<span class="explain">no variables yet</span>';
    $(".wkS", el).innerHTML = f.say; $(".wkO", el).textContent = (f.out || []).join("\n") || "(nothing printed yet)"; $(".wkL", el).classList.toggle("on", !!f.led); $(".wkLw", el).hidden = !o.led;
    $(".wkN", el).textContent = `Step ${Math.min(i, fr.length - 1) + 1} of ${fr.length}`; $(".wkB", el).disabled = i === 0; $(".wkF", el).disabled = i >= fr.length - 1; if (i >= fr.length - 1) markAct(o.id, "done"); };
  el.innerHTML = bench(o.title, `${o.intro ? `<p>${o.intro}</p>` : ""}${o.ctl || ""}<div class="walk"><div class="codebox"><pre class="code wkC" style="padding:8px"></pre></div><div><p class="explain">Variables (the named boxes in memory)</p><div class="vars wkV"></div><div class="wkLw" hidden><p class="explain">LED</p><div class="big-led wkL" style="width:40px;height:40px"></div></div><p class="explain">Serial Monitor output</p><pre class="serial static wkO" style="min-height:3em"></pre></div></div>
   <div class="say wkS" aria-live="polite"></div><div class="controls"><button class="btn wkB" type="button">◀ Back</button><button class="btn primary wkF" type="button">Next step ▶</button><button class="btn wkR" type="button">Restart</button><span class="explain wkN"></span></div>`);
  $(".wkF", el).onclick = () => { i++; draw(); }; $(".wkB", el).onclick = () => { i = Math.max(0, i - 1); draw(); }; $(".wkR", el).onclick = () => { i = 0; draw(); };
  el.querySelectorAll(".dsel").forEach(s => s.onchange = () => { i = 0; if (o.onctl) o.onctl(s); draw(); });
  draw();
}
INTERACTIVES.walkVars = el => walkEngine(el, {id:"walkVars", title:"Step through: variables", intro:"A <b>variable</b> is a labelled box in the board's memory. Press <b>Next step</b> and watch each line run, one at a time.",
  lines:["int count = 0;", "float tempC = 24.5;", "bool alarm = false;", "count = count + 1;", "tempC = tempC + 1.5;", "if (tempC > 25) {", "  alarm = true;", "}"],
  frames:() => [{ln:0, vars:{count:0}, say:"<b>Create a box</b> named <code>count</code>, of type <code>int</code> (whole numbers), and put 0 in it."}, {ln:1, vars:{count:0, tempC:"24.5"}, say:"A second box, <code>tempC</code>, of type <code>float</code> (decimal numbers), holding 24.5."},
   {ln:2, vars:{count:0, tempC:"24.5", alarm:"false"}, say:"A <code>bool</code> box can only hold <b>true</b> or <b>false</b>. It starts as false: no alarm."}, {ln:3, vars:{count:1, tempC:"24.5", alarm:"false"}, say:"<b>Read, change, store.</b> Read the box (0), add 1, and put the answer (1) back into the same box. In maths <code>count = count + 1</code> would be impossible; in code <code>=</code> means “store”."},
   {ln:4, vars:{count:1, tempC:"26", alarm:"false"}, say:"24.5 + 1.5 = 26. The box now holds 26."}, {ln:5, vars:{count:1, tempC:"26", alarm:"false"}, say:"<b>A question:</b> is <code>tempC &gt; 25</code>? 26 is greater than 25, so the answer is <b>yes</b>: run the block below."},
   {ln:6, vars:{count:1, tempC:"26", alarm:"true"}, say:"The alarm box changes to <b>true</b>. This is how a program remembers things: in variables."}, {ln:7, vars:{count:1, tempC:"26", alarm:"true"}, say:"End of the block. The program carries on with the next line."}]});
INTERACTIVES.walkFor = el => { let N = 3; walkEngine(el, {id:"walkFor", title:"Step through: a for loop", intro:"A <code>for</code> loop repeats a block a fixed number of times. Choose how many blinks, then step through.",
  ctl:`<div class="controls"><label>Number of blinks <select class="dinput dsel" data-c="n">${[1, 2, 3, 4].map(n => `<option value="${n}" ${n === 3 ? "selected" : ""}>${n}</option>`).join("")}</select></label></div>`, onctl:s => { N = +s.value; }, led:true,
  lines:() => [`for (int i = 0; i < ${N}; i++) {`, "  digitalWrite(LED_PIN, HIGH); delay(150);", "  digitalWrite(LED_PIN, LOW);  delay(150);", "}", "// loop finished"],
  frames:() => { const f = [{ln:0, vars:{i:0}, say:`<b>Start.</b> Create <code>i</code> and set it to 0. Is <code>i &lt; ${N}</code>? 0 &lt; ${N}: yes, run the block.`}]; let blinks = 0;
    for (let i = 0; i < N; i++){ f.push({ln:1, vars:{i}, led:true, say:`LED <b>on</b>, wait 150 ms. (This is blink number ${i + 1} of ${N}.)`}); f.push({ln:2, vars:{i}, led:false, say:"LED <b>off</b>, wait 150 ms."}); blinks++;
      f.push({ln:0, vars:{i:i + 1}, say:`<b>End of the block: i++ adds 1</b>, so i is now ${i + 1}. Check again: is ${i + 1} &lt; ${N}? <b>${i + 1 < N ? "Yes, go round again." : "No, so the loop stops."}</b>`}); }
    f.push({ln:4, vars:{i:N}, led:false, say:`The loop is finished after exactly <b>${N}</b> blinks. The <code>for</code> loop counted for us.`}); return f; }}); };
INTERACTIVES.walkFunc = el => { let C = 30; walkEngine(el, {id:"walkFunc", title:"Step through: a function", intro:"A function is a <b>mini-program with a name</b>. You give it something (the argument), it works, and it gives something back (the return value).",
  ctl:`<div class="controls"><label>Temperature to convert (°C) <select class="dinput dsel" data-c="c">${[0, 25, 30, 100].map(n => `<option value="${n}" ${n === 30 ? "selected" : ""}>${n}</option>`).join("")}</select></label></div>`, onctl:s => { C = +s.value; },
  lines:() => ["float toFahrenheit(float c) {", "  return c * 9.0 / 5.0 + 32.0;", "}", "", "void loop() {", `  float tempC = ${C.toFixed(1)};`, "  float tempF = toFahrenheit(tempC);", "  Serial.println(tempF);", "}"],
  frames:() => { const F = C * 9 / 5 + 32; return [{ln:5, vars:{tempC:C.toFixed(1)}, say:`In <code>loop()</code>, store ${C} in <code>tempC</code>.`}, {ln:6, vars:{tempC:C.toFixed(1)}, say:"<b>Call the function.</b> The program pauses here and jumps up to <code>toFahrenheit</code>, carrying the value of <code>tempC</code> with it."},
    {ln:0, vars:{tempC:C.toFixed(1), c:C.toFixed(1)}, say:`The value is <b>copied</b> into the function's own box <code>c</code>. <code>c</code> only exists inside the function.`}, {ln:1, vars:{tempC:C.toFixed(1), c:C.toFixed(1)}, say:`Calculate: ${C} × 9.0 ÷ 5.0 + 32.0 = <b>${F.toFixed(1)}</b>. <code>return</code> sends that number back to where the function was called.`},
    {ln:6, vars:{tempC:C.toFixed(1), tempF:F.toFixed(1)}, say:`Back in <code>loop()</code>: the answer ${F.toFixed(1)} is stored in <code>tempF</code>.`}, {ln:7, vars:{tempC:C.toFixed(1), tempF:F.toFixed(1)}, out:[F.toFixed(2)], say:`Print it. <code>Serial.println</code> shows two decimals by default: <b>${F.toFixed(2)}</b>.`}]; }}); };

/* ---------- 1.4 decisions: a live flow chart ---------- */
INTERACTIVES.ifLab = function(el){
  el.innerHTML = bench("Decisions with if / else if / else", `<p>The board asks its questions <b>from top to bottom</b> and runs the block of the <b>first question answered “yes”</b>. Then it skips the rest.</p>
   <div class="controls"><label>Temperature <input type="range" class="ifT" min="0" max="45" step="0.5" value="24"></label><span class="rangeval ifTv"></span></div>
   <div class="controls"><label>“Too hot” above <input type="range" class="ifH" min="20" max="40" step="1" value="30"></label><span class="rangeval ifHv"></span><label>“Too cold” below <input type="range" class="ifC" min="5" max="25" step="1" value="18"></label><span class="rangeval ifCv"></span></div>
   <div class="walk"><div class="codebox"><pre class="code ifCode" style="padding:8px"></pre></div><svg class="flowsvg ifSvg" viewBox="0 0 330 230" role="img" aria-label="Flow chart of the decision"></svg></div><div class="say ifS"></div>`);
  const draw = () => { const t = +$(".ifT", el).value, h = +$(".ifH", el).value, c = +$(".ifC", el).value; $(".ifTv", el).textContent = t.toFixed(1) + " °C"; $(".ifHv", el).textContent = h + " °C"; $(".ifCv", el).textContent = c + " °C";
    const br = t > h ? 0 : t < c ? 1 : 2; const L = [`if (tempC > ${h}) {`, "  digitalWrite(FAN_PIN, HIGH);", `} else if (tempC < ${c}) {`, "  digitalWrite(HEATER_PIN, HIGH);", "} else {", "  // comfortable: do nothing", "}"], hot = br === 0 ? [0, 1] : br === 1 ? [2, 3] : [4, 5]; const skipped = br === 0 ? [2, 3, 4, 5] : br === 1 ? [4, 5] : [];
    $(".ifCode", el).innerHTML = `<div class="codeline">float tempC = ${t.toFixed(1)};</div>` + L.map((l, k) => `<div class="codeline ${hot.includes(k) ? "hl" : skipped.includes(k) ? "skip" : ""}">${esc(l)}</div>`).join("");
    const a = "#F59E0B", n = "#94A3B8", st = (on) => on ? `stroke="${a}" stroke-width="4"` : `stroke="${n}" stroke-width="2"`, fl = on => on ? a : "var(--surface)";
    $(".ifSvg", el).innerHTML = `<defs><marker id="ifar" viewBox="0 0 8 8" refX="6" refY="4" markerUnits="userSpaceOnUse" markerWidth="10" markerHeight="10" orient="auto"><path d="M0 0 8 4 0 8z" fill="#64748B"/></marker></defs>
     <rect x="100" y="4" width="130" height="26" rx="8" fill="var(--surface)" stroke="#64748B"/><text x="165" y="22" text-anchor="middle" class="svgtxt b">tempC = ${t.toFixed(1)}</text><path d="M165 30 V44" stroke="${a}" stroke-width="4" marker-end="url(#ifar)"/>
     <path d="M165 44 L235 72 L165 100 L95 72 Z" fill="${fl(br === 0)}" ${st(true)}/><text x="165" y="76" text-anchor="middle" class="svgtxt b">&gt; ${h} ?</text>
     <path d="M235 72 H290 V110" fill="none" ${st(br === 0)} marker-end="url(#ifar)"/><text x="262" y="66" class="svgtxt">yes</text><rect x="240" y="110" width="80" height="30" rx="8" fill="${fl(br === 0)}" ${st(br === 0)}/><text x="280" y="129" text-anchor="middle" class="svgtxt b">fan ON</text>
     <path d="M165 100 V116" fill="none" ${st(br > 0)} marker-end="url(#ifar)"/><text x="172" y="112" class="svgtxt">no</text>
     <path d="M165 116 L235 142 L165 168 L95 142 Z" fill="${fl(br === 1)}" ${st(br > 0)}/><text x="165" y="146" text-anchor="middle" class="svgtxt b">&lt; ${c} ?</text>
     <path d="M95 142 H40 V180" fill="none" ${st(br === 1)} marker-end="url(#ifar)"/><text x="62" y="136" class="svgtxt">yes</text><rect x="4" y="180" width="80" height="30" rx="8" fill="${fl(br === 1)}" ${st(br === 1)}/><text x="44" y="199" text-anchor="middle" class="svgtxt b">heater ON</text>
     <path d="M165 168 V180" fill="none" ${st(br === 2)} marker-end="url(#ifar)"/><text x="172" y="178" class="svgtxt">no</text><rect x="110" y="182" width="110" height="30" rx="8" fill="${fl(br === 2)}" ${st(br === 2)}/><text x="165" y="201" text-anchor="middle" class="svgtxt b">do nothing</text>`;
    $(".ifS", el).innerHTML = br === 0 ? `<b>${t.toFixed(1)} &gt; ${h}: yes.</b> The fan turns on. The board skips the other questions.` : br === 1 ? `<b>${t.toFixed(1)} &gt; ${h}: no. ${t.toFixed(1)} &lt; ${c}: yes.</b> The heater turns on.` : `<b>Both questions answered no</b>, so the <code>else</code> block runs: the room is comfortable.` + (c >= h ? " (Your thresholds overlap: that is a bug in a real program!)" : "");
    markAct("ifLab", "used"); };
  el.querySelectorAll("input").forEach(x => x.oninput = draw); draw();
};

/* ---------- 1.4 timing: how millis() decides ---------- */
INTERACTIVES.millisClock = function(el){
  el.innerHTML = bench("How millis() lets two jobs share one board", `<p>Instead of stopping with <code>delay()</code>, the board runs <code>loop()</code> thousands of times a second and each time asks: <b>“has enough time passed?”</b> Slide the clock forward and watch the two variables.</p>
   <div class="controls"><label>Clock: millis() <input type="range" class="mcT" min="0" max="3000" step="10" value="0"></label><span class="rangeval mcTv"></span><label>Interval (ms) <select class="dinput mcI"><option>250</option><option selected>500</option><option>1000</option></select></label></div>
   <div class="walk"><div class="codebox"><pre class="code" style="padding:8px"><div class="codeline">const unsigned long interval = <b class="mcIv"></b>;</div><div class="codeline">unsigned long previous = 0;</div><div class="codeline"> </div><div class="codeline">void loop() {</div><div class="codeline mcL1">  unsigned long now = millis();</div><div class="codeline mcL2">  if (now - previous >= interval) {</div><div class="codeline mcL3">    previous = now;</div><div class="codeline mcL4">    ledState = !ledState;  // flip</div><div class="codeline">  }</div><div class="codeline">  // other jobs run here, every pass</div><div class="codeline">}</div></pre></div>
   <div><div class="vars"><div class="vb"><small>now</small><b class="mcN"></b></div><div class="vb"><small>previous</small><b class="mcP"></b></div><div class="vb"><small>now − previous</small><b class="mcD"></b></div></div><div class="big-led mcLed" style="width:44px;height:44px;margin:6px 0"></div></div></div>
   <svg class="flowsvg mcSvg" viewBox="0 0 640 80" role="img" aria-label="Timeline of the LED"></svg><div class="say mcS"></div>`);
  const draw = () => { const T = +$(".mcT", el).value, I = +$(".mcI", el).value; let prev = 0, led = false, last = null; const segs = [];
    for (let now = 0; now <= T; now += 10){ if (now - prev >= I){ prev = now; led = !led; segs.push(now); } }
    const sampleNow = T, diff = T - prev;
    $(".mcTv", el).textContent = T + " ms"; $(".mcIv", el).textContent = I; $(".mcN", el).textContent = T; $(".mcP", el).textContent = prev; $(".mcD", el).textContent = diff; $(".mcLed", el).classList.toggle("on", led);
    const X = t => 20 + t / 3000 * 600; let h = ""; let st = false, last0 = 0; const toggles = []; { let p = 0; for (let n = 0; n <= 3000; n += 10) if (n - p >= I){ p = n; toggles.push(n); } }
    const pts = [0].concat(toggles, [3000]); for (let k = 0; k < pts.length - 1; k++){ const on = k % 2 === 1; h += `<rect x="${X(pts[k])}" y="${on ? 14 : 38}" width="${X(pts[k + 1]) - X(pts[k])}" height="${on ? 24 : 0}" fill="#EF4444" opacity=".85"/>`; h += `<path d="M${X(pts[k])} ${on ? 14 : 38} H${X(pts[k + 1])}" stroke="#EF4444" stroke-width="3"/>`; if (!on) h += ``; }
    h += `<path d="M20 38 H620" stroke="#94A3B8"/><text x="20" y="62" class="svgtxt mute">0 s</text><text x="320" y="62" class="svgtxt mute">1.5 s</text><text x="600" y="62" class="svgtxt mute">3 s</text><path d="M${X(T)} 6 V50" stroke="#4F46E5" stroke-width="3"/><circle cx="${X(T)}" cy="6" r="5" fill="#4F46E5"/><text x="40" y="12" class="svgtxt b" fill="#B91C1C">LED is ON where the red bar is raised</text>`;
    $(".mcSvg", el).innerHTML = h;
    $(".mcL2", el).classList.toggle("hl", diff >= I); $(".mcL3", el).classList.toggle("hl", diff >= I); $(".mcL4", el).classList.toggle("hl", diff >= I); $(".mcL1", el).classList.add("hl");
    $(".mcS", el).innerHTML = diff >= I ? `<b>${T} − ${prev} = ${diff}</b>, which is at least ${I}. The question is <b>yes</b>: remember this moment (<code>previous = now</code>) and flip the LED.` : `<b>${T} − ${prev} = ${diff}</b>, which is less than ${I}. <b>Not yet</b>: do nothing, and go on to the other jobs. The board is free to read buttons and sensors meanwhile.`; markAct("millisClock", "used"); };
  el.querySelectorAll("input,select").forEach(x => x.oninput = x.onchange = draw); draw();
};

/* ---------- 1.4 code detective: predict, order, find the bug (no typing needed) ---------- */
INTERACTIVES.codeDetective = function(el){
  const PRED = [
   {code:"int total = 0;\nfor (int i = 1; i <= 4; i++) {\n  total = total + i;\n}\nSerial.println(total);", o:["4", "6", "10", "15"], a:2, why:"The loop adds i = 1, 2, 3, 4: 0 + 1 = 1, + 2 = 3, + 3 = 6, + 4 = 10. The loop runs while i &lt;= 4, so 4 is included. (15 would be 5 numbers.)"},
   {code:"int x = 7;\nif (x > 5) {\n  Serial.println(\"big\");\n} else {\n  Serial.println(\"small\");\n}\nif (x > 8) {\n  Serial.println(\"huge\");\n}", o:["big", "small", "big, then huge", "small, then huge"], a:0, why:"7 &gt; 5 is true, so “big” prints and the else block is skipped. The second <code>if</code> is a separate question: 7 &gt; 8 is false, so nothing prints."},
   {code:"Serial.println(7 / 2);\nSerial.println(7 / 2.0);", o:["3 then 3.50", "3.5 then 3.5", "3.50 then 3.50", "4 then 3.50"], a:0, why:"With two whole numbers, C++ divides and <b>drops the remainder</b>: 7 / 2 = 3. When one number has a decimal point (2.0) the answer keeps decimals: 3.50 (Arduino prints two decimals)."},
   {code:"int twice(int n) {\n  return n * 2;\n}\n// ...\nSerial.println(twice(twice(3)));", o:["6", "9", "12", "3"], a:2, why:"Work from the inside out: twice(3) = 6, then twice(6) = 12."}];
  const ORD = [
   {title:"Traffic light", intro:"Put the chunks in the order the board needs them.", chunks:[["const int RED = 4;\nconst int GREEN = 5;", "Names first: the rest of the code uses them."], ["void setup() {\n  pinMode(RED, OUTPUT);\n  pinMode(GREEN, OUTPUT);\n}", "setup() runs once, to prepare the pins."], ["void loop() {\n  digitalWrite(RED, HIGH);\n  delay(2000);", "Start of loop(): red on, hold for 2 seconds."], ["  digitalWrite(RED, LOW);\n  digitalWrite(GREEN, HIGH);\n  delay(2000);", "Red off, then green on, hold for 2 seconds."], ["  digitalWrite(GREEN, LOW);\n}", "Green off, then the loop ends and starts again with red."]]},
   {title:"Blink twice, then pause", intro:"Order the chunks so the LED does two short blinks and a long pause.", chunks:[["const int LED_PIN = 6;", "Name the pin."], ["void setup() {\n  pinMode(LED_PIN, OUTPUT);\n}", "Prepare the pin once."], ["void loop() {\n  digitalWrite(LED_PIN, HIGH); delay(100);\n  digitalWrite(LED_PIN, LOW);  delay(100);", "Blink one."], ["  digitalWrite(LED_PIN, HIGH); delay(100);\n  digitalWrite(LED_PIN, LOW);  delay(1000);\n}", "Blink two, then the long pause before the loop repeats."]]}];
  const BUG = [
   {code:["const int LED_PIN = 6;", "void setup() {", "  pinMode(LED_PIN, OUTPUT)", "}", "void loop() {", "  digitalWrite(LED_PIN, HIGH);", "  delay(500);", "}"], bug:2, msg:"error: expected ';' before '}' token", why:"Every instruction ends with a semicolon. Line 3 is missing one. (The compiler often reports the problem on the line <b>after</b> the real mistake.)", fix:"  pinMode(LED_PIN, OUTPUT);"},
   {code:["void setup() {", "  pinmode(6, OUTPUT);", "}", "void loop() {", "  digitalWrite(6, HIGH);", "}"], bug:1, msg:"error: 'pinmode' was not declared in this scope", why:"C++ cares about capital letters. The command is <code>pinMode</code> with a capital M.", fix:"  pinMode(6, OUTPUT);"},
   {code:["int button = 2;", "void loop() {", "  if (digitalRead(button) = LOW) {", "    Serial.println(\"pressed\");", "  }", "}"], bug:2, msg:"error: lvalue required as left operand of assignment", why:"A single <code>=</code> <b>stores</b> a value. To <b>ask</b> “are they equal?” you need two: <code>==</code>.", fix:"  if (digitalRead(button) == LOW) {"},
   {code:["int a = 3;", "int b = 4;", "float average = (a + b) / 2;", "Serial.println(average);"], bug:2, msg:"No error, but it prints 3.00 instead of 3.50", why:"<code>(a + b) / 2</code> divides two whole numbers, so the remainder is dropped (7 / 2 = 3) before it is stored in the float. Divide by <code>2.0</code>.", fix:"float average = (a + b) / 2.0;"},
   {code:["void loop() {", "  digitalWrite(LED_PIN, HIGH);", "  digitalWrite(LED_PIN, LOW);", "}"], bug:-1, msg:"The LED looks dimly lit and never visibly blinks", why:"There is no <code>delay()</code> after turning the LED on or off, so it switches thousands of times a second. The bug is a <b>missing</b> line: tap “the problem is something missing” and add waits."}];
  let lvl = 0, pi = 0, oi = 0, bi = 0, score = {p:0, o:0, b:0}, order = [], done = new Set();
  const shuffle = (n, seed) => { const a = Array.from({length:n}, (_, i) => i); for (let i = n - 1; i > 0; i--){ const j = (seed * 7 + i * 3) % (i + 1); [a[i], a[j]] = [a[j], a[i]]; } if (a.every((v, i) => v === i)) a.reverse(); return a; };
  const render = () => {
    let body = "";
    if (lvl === 0){ const q = PRED[pi]; body = `<p><span class="lvl-pill">Level 1 · Predict</span> Read the code like the board does, top to bottom. <b>What appears in the Serial Monitor?</b></p><pre class="code" style="padding:8px"><code>${esc(q.code)}</code></pre><div class="choicecards dcO">${q.o.map((o, k) => `<button type="button" data-k="${k}">${esc(o)}</button>`).join("")}</div><div class="ix-out dcX" hidden></div>`; }
    else if (lvl === 1){ const c = ORD[oi]; if (!order.length || order.length !== c.chunks.length) order = shuffle(c.chunks.length, oi + 3); body = `<p><span class="lvl-pill">Level 2 · Put it in order</span> <b>${c.title}.</b> ${c.intro} Use the arrows to move a chunk.</p><div class="dcList">${order.map((k, pos) => `<div class="codebox" style="display:flex;gap:6px;align-items:stretch"><pre class="code" style="flex:1;padding:6px;margin:0"><code>${esc(c.chunks[k][0])}</code></pre><span style="display:flex;flex-direction:column;gap:4px;padding:4px"><button class="btn small dcUp" data-p="${pos}" type="button" aria-label="Move up">▲</button><button class="btn small dcDn" data-p="${pos}" type="button" aria-label="Move down">▼</button></span></div>`).join("")}</div><div class="controls"><button class="btn primary dcChk" type="button">Check the order</button></div><div class="ix-out dcX" hidden></div>`; }
    else { const c = BUG[bi]; body = `<p><span class="lvl-pill">Level 3 · Find the bug</span> The board reports: <code>${esc(c.msg)}</code><br><b>Tap the line that has the problem.</b></p><div class="codebox"><div class="code" style="padding:6px">${c.code.map((l, k) => `<button type="button" class="codeline dcLn" data-k="${k}" style="display:block;width:100%;text-align:left;background:none;border:0;cursor:pointer;color:inherit">${String(k + 1).padStart(2, " ")}  ${esc(l)}</button>`).join("")}</div></div>${c.bug < 0 ? `<div class="controls"><button class="btn dcMissing" type="button">The problem is something missing</button></div>` : ""}<div class="ix-out dcX" hidden></div>`; }
    el.innerHTML = bench("Code detective: three levels, no typing", `<div class="seg seg-sm dcT">${["1. Predict", "2. Order", "3. Find the bug"].map((t, i) => `<button type="button" data-t="${i}" aria-selected="${i === lvl}">${t}${done.has(i) ? " ✓" : ""}</button>`).join("")}</div>${body}<div class="controls"><button class="btn small dcNext" type="button">Next puzzle ▶</button><span class="explain">Score: predict ${score.p}, order ${score.o}, bugs ${score.b}. Solve 3 at each level for the badge.</span></div>`);
    el.querySelectorAll(".dcT button").forEach(b => b.onclick = () => { lvl = +b.dataset.t; order = []; render(); });
    $(".dcNext", el).onclick = () => { if (lvl === 0) pi = (pi + 1) % PRED.length; else if (lvl === 1){ oi = (oi + 1) % ORD.length; order = []; } else bi = (bi + 1) % BUG.length; render(); };
    const fb = (ok, html) => { const x = $(".dcX", el); x.hidden = false; x.innerHTML = (ok ? "<b>✓ Yes.</b> " : "<b>✗ Not quite.</b> ") + html; };
    const win = k => { score[k]++; const lv = {p:0, o:1, b:2}[k]; if (score[k] >= 3) done.add(lv); if (done.size === 3) markAct("codeDetective", "done"); const s = $(".dcNext", el).nextElementSibling; s.textContent = `Score: predict ${score.p}, order ${score.o}, bugs ${score.b}. Solve 3 at each level for the badge.`; };
    if (lvl === 0) el.querySelectorAll(".dcO button").forEach(b => b.onclick = () => { const q = PRED[pi], ok = +b.dataset.k === q.a; b.classList.add(ok ? "ok" : "no"); fb(ok, q.why); if (ok) win("p"); });
    if (lvl === 1){ el.querySelectorAll(".dcUp,.dcDn").forEach(b => b.onclick = () => { const p = +b.dataset.p, q = b.classList.contains("dcUp") ? p - 1 : p + 1; if (q < 0 || q >= order.length) return; [order[p], order[q]] = [order[q], order[p]]; render(); });
      $(".dcChk", el).onclick = () => { const c = ORD[oi], good = order.every((k, p) => k === p); if (good){ fb(true, c.chunks.map((x, i) => `${i + 1}. ${x[1]}`).join(" ")); win("o"); } else { const bad = order.findIndex((k, p) => k !== p); fb(false, `Position ${bad + 1} is not right yet. Think: what must the board do <i>first</i>? Hint: names and setup come before loop().`); } }; }
    if (lvl === 2){ el.querySelectorAll(".dcLn").forEach(b => b.onclick = () => { const c = BUG[bi], k = +b.dataset.k, ok = k === c.bug; b.classList.add(ok ? "hl" : "skip"); fb(ok, ok ? `${c.why} <br>Fixed line: <code>${esc(c.fix)}</code>` : "That line is fine. Read the message again and look at the others."); if (ok) win("b"); });
      const m = $(".dcMissing", el); if (m) m.onclick = () => { const c = BUG[bi], ok = c.bug < 0; fb(ok, ok ? c.why : "There is a line with a mistake: tap it."); if (ok) win("b"); }; }
  };
  render();
};

/* ---------- 1.5 parts: how they work inside ---------- */
const PART_NOTE = {};
INTERACTIVES.partLed = function(el){
  let V = 2.0, flip = false, hot = null;
  const HOT = {dome:["The dome", "A clear (or tinted) plastic lens. It shapes the light and protects the tiny chip inside."], flat:["The flat edge", "A flat side on the rim marks the <b>cathode (−)</b>, the short leg's side. Handy when the legs have been trimmed."], long:["The long leg: anode (+)", "Current goes <b>in</b> here. A new LED has one long leg so you can tell the sides apart. Connect this one toward the pin (through a resistor)."], short:["The short leg: cathode (−)", "Current comes <b>out</b> here and goes on toward GND."], chip:["The chip (die)", "A tiny crystal of semiconductor, smaller than a grain of salt. When current passes through it, it gives off light. Its colour depends on the crystal, not on the plastic."], anvil:["Anvil and post", "Inside, the cathode leg ends in a bigger plate (the <b>anvil</b>) that holds the chip; the anode leg ends in a thinner <b>post</b>. If you can see inside, the bigger plate is the − side."]};
  el.innerHTML = bench("Inside an LED", `<div class="ix-grid2"><div><svg class="partsvg plSvg" viewBox="0 0 320 280" role="img" aria-label="Diagram of an LED with labelled parts. Tap a part."></svg><p class="explain">Tap a part of the LED to learn what it is.</p><div class="ix-out plN" aria-live="polite">Tap any part.</div></div>
   <div><p><b>Make it glow.</b> An LED is a one-way valve for current. Raise the voltage across it:</p><div class="controls"><label>Voltage across the LED <input type="range" class="plV" min="0" max="2.6" step="0.05" value="${V}"></label><span class="rangeval plVv"></span></div>
    <div class="controls"><label class="chk"><input type="checkbox" class="plF"><span>Turn the LED around (swap the legs)</span></label></div>
    <div class="big-led plL" style="margin:8px auto"></div><div class="ix-out plO"></div></div></div>`);
  const draw = () => { const svg = $(".plSvg", el); const s = x => hot === x ? "sel" : "";
    svg.innerHTML = `<g class="hot ${s("dome")}" data-k="dome" tabindex="0" role="button" aria-label="Dome"><path d="M90 150 V90 a70 70 0 0 1 140 0 V150 Z" fill="#FCA5A5" stroke="#7F1D1D" stroke-width="3" opacity=".9"/></g>
     <g class="hot ${s("flat")}" data-k="flat" tabindex="0" role="button" aria-label="Flat edge"><rect x="226" y="136" width="14" height="26" fill="#FCA5A5" stroke="#7F1D1D" stroke-width="3"/><path d="M233 118 V162" stroke="#7F1D1D" stroke-width="4"/></g><rect x="80" y="150" width="150" height="14" rx="2" fill="#FCA5A5" stroke="#7F1D1D" stroke-width="3"/>
     <g class="hot ${s("anvil")}" data-k="anvil" tabindex="0" role="button" aria-label="Anvil and post"><path d="M130 150 V84 M120 84 H160 L155 70 H125 Z" fill="#9CA3AF" stroke="#4B5563" stroke-width="4"/><path d="M190 150 V70" stroke="#9CA3AF" stroke-width="4"/></g>
     <g class="hot ${s("chip")}" data-k="chip" tabindex="0" role="button" aria-label="Chip"><rect x="130" y="62" width="24" height="10" fill="#FBBF24" stroke="#92400E" stroke-width="2"/></g>
     <g class="hot ${s("long")}" data-k="long" tabindex="0" role="button" aria-label="Long leg, anode"><path d="M110 164 V268" stroke="#D1D5DB" stroke-width="9" stroke-linecap="round"/><path d="M110 164 V268" stroke="#9CA3AF" stroke-width="3"/></g>
     <g class="hot ${s("short")}" data-k="short" tabindex="0" role="button" aria-label="Short leg, cathode"><path d="M200 164 V236" stroke="#D1D5DB" stroke-width="9" stroke-linecap="round"/><path d="M200 164 V236" stroke="#9CA3AF" stroke-width="3"/></g>
     <text x="110" y="278" text-anchor="middle" style="fill:#B91C1C;font-size:18px">+</text><text x="200" y="256" text-anchor="middle" style="fill:#1D4ED8;font-size:22px">−</text>
     <text x="10" y="30" style="font-size:11px">dome</text><path d="M44 26 L104 56" stroke="#64748B"/><text x="252" y="128" style="font-size:11px">flat edge</text><text x="10" y="210" style="font-size:11px">long leg</text><text x="10" y="224" style="font-size:11px">(anode +)</text><text x="222" y="214" style="font-size:11px">short leg</text><text x="222" y="228" style="font-size:11px">(cathode −)</text>`;
    svg.querySelectorAll(".hot").forEach(g => { const go = () => { hot = g.dataset.k; $(".plN", el).innerHTML = `<b>${HOT[hot][0]}.</b> ${HOT[hot][1]}`; draw(); markAct("partLed", "used"); }; g.onclick = go; g.onkeydown = e => { if (e.key === "Enter" || e.key === " "){ e.preventDefault(); go(); } }; }); };
  const upd = () => { V = +$(".plV", el).value; flip = $(".plF", el).checked; const I = flip || V < 1.6 ? 0 : 0.3 * (Math.exp((V - 1.6) / 0.15) - 1); const mA = Math.min(I, 400);
    $(".plVv", el).textContent = V.toFixed(2) + " V"; const L = $(".plL", el); const g = clampN(mA / 20, 0, 1.2); L.style.background = mA > 30 ? "#374151" : `rgb(${Math.round(127 + 121 * Math.min(1, g))},${Math.round(29 + 84 * Math.min(1, g))},${Math.round(29 + 84 * Math.min(1, g))})`; L.style.boxShadow = mA > 0.5 && mA <= 30 ? `0 0 ${10 + g * 24}px ${g * 12}px rgba(248,113,113,${Math.min(.8, g)})` : "none";
    $(".plO", el).innerHTML = `<div class="kv"><span>Current</span><b>${mA < 100 ? mA.toFixed(1) : Math.round(mA)} mA</b></div><p class="explain">${flip ? "The LED is the wrong way round: it blocks the current completely, so it never lights. (This is safe for the LED; just flip it back.)" : V < 1.6 ? "Below about 1.6 V nothing flows: the LED is dark. Every colour has its own “turn-on voltage”." : mA > 30 ? "<b>Too much current: this LED would burn out.</b> Notice how a tiny rise in voltage caused a huge rise in current." : mA > 20 ? "At the limit (20 mA). Any more and the LED will be damaged." : "Light! Raise the voltage slowly: between 2.0 V and 2.3 V the current rockets from a few mA to dangerous levels. That is why an LED always needs a resistor to limit the current."}</p>`; };
  $(".plV", el).oninput = $(".plF", el).onchange = upd; draw(); upd();
};
INTERACTIVES.partRgb = function(el){
  let r = 255, g = 60, b = 120, ca = false;
  el.innerHTML = bench("Inside an RGB LED: three LEDs in one", `<div class="ix-grid2"><div><svg class="partsvg" viewBox="0 0 320 250" role="img" aria-label="RGB LED with four legs: red, common, green, blue"><circle class="rgPrev" cx="160" cy="84" r="52" fill="#fff" stroke="#374151" stroke-width="3"/>
     <path d="M110 142 H210" stroke="#374151" stroke-width="4"/>${[["R", 118, "#DC2626", 150, "red"], ["longest: common", 142, "#111827", 205, ca ? "common ANODE (+)" : "common CATHODE (−)"], ["G", 178, "#16A34A", 150, "green"], ["B", 202, "#2563EB", 150, "blue"]].map(l => `<path d="M${l[1] + 6} 142 V${l[3] + 30}" stroke="#9CA3AF" stroke-width="6" stroke-linecap="round"/><text x="${l[1] + 6}" y="${l[3] + 46}" text-anchor="middle" style="fill:${l[2]};font-weight:800">${l[0] === "longest: common" ? "" : l[0]}</text>`).join("")}
     <text x="148" y="246" text-anchor="middle" style="fill:#111827;font-size:10px">longest leg</text><text x="160" y="14" text-anchor="middle" style="font-size:11px">Flat edge to the left, legs read:</text><text x="160" y="27" text-anchor="middle" style="font-size:11px">R · longest · G · B</text></svg>
     <p class="explain">Four legs: one for each colour, plus a <b>common</b> leg shared by all three. On a <b>common-cathode</b> LED the common leg goes to GND; on a <b>common-anode</b> LED it goes to + power.</p></div>
    <div><div class="controls"><label style="color:#DC2626">Red <input type="range" class="rgR" min="0" max="255" value="${r}"></label><span class="rangeval rgRv"></span></div><div class="controls"><label style="color:#16A34A">Green <input type="range" class="rgG" min="0" max="255" value="${g}"></label><span class="rangeval rgGv"></span></div><div class="controls"><label style="color:#2563EB">Blue <input type="range" class="rgB" min="0" max="255" value="${b}"></label><span class="rangeval rgBv"></span></div>
     <div class="controls"><label class="chk"><input type="checkbox" class="rgCa"><span>My LED is common anode</span></label></div><div class="controls">${[["Red", 255, 0, 0], ["Yellow", 255, 255, 0], ["Cyan", 0, 255, 255], ["Purple", 160, 32, 240], ["White", 255, 255, 255]].map(c => `<button class="btn small rgP" type="button" data-c="${c.slice(1)}">${c[0]}</button>`).join("")}</div>
     <div class="codebox"><pre class="code"><code class="rgCode"></code></pre></div><p class="explain rgN"></p></div></div>`);
  const draw = () => { r = +$(".rgR", el).value; g = +$(".rgG", el).value; b = +$(".rgB", el).value; ca = $(".rgCa", el).checked; $(".rgPrev", el).setAttribute("fill", `rgb(${r},${g},${b})`); $(".rgRv", el).textContent = r + " (" + Math.round(r / 2.55) + " %)"; $(".rgGv", el).textContent = g + " (" + Math.round(g / 2.55) + " %)"; $(".rgBv", el).textContent = b + " (" + Math.round(b / 2.55) + " %)";
    const w = v => ca ? 255 - v : v; $(".rgCode", el).textContent = `analogWrite(RED_PIN,   ${w(r)});\nanalogWrite(GREEN_PIN, ${w(g)});\nanalogWrite(BLUE_PIN,  ${w(b)});`; $(".rgN", el).innerHTML = ca ? "<b>Common anode runs backwards:</b> 255 means OFF and 0 means full brightness, so the code subtracts each value from 255." : "Mix light, not paint: red + green = yellow, all three at full = white. Each number is how long the pin stays on in each tiny time slice (PWM)."; markAct("partRgb", "used"); };
  el.querySelectorAll("input").forEach(x => x.oninput = draw); el.querySelectorAll(".rgP").forEach(x => x.onclick = () => { const c = x.dataset.c.split(",").map(Number); $(".rgR", el).value = c[0]; $(".rgG", el).value = c[1]; $(".rgB", el).value = c[2]; draw(); }); draw();
};
INTERACTIVES.partButton = function(el){
  let down = false, deb = false, presses = [];
  el.innerHTML = bench("Inside a pushbutton, and why it bounces", `<div class="ix-grid2"><div><svg class="partsvg pbSvg" viewBox="0 0 320 260" role="img" aria-label="Four-leg pushbutton, top view, with internal connections"></svg><div class="controls"><button class="btn primary pbBtn" type="button">Hold to press</button></div><p class="explain">A tactile button has <b>four legs</b>. The two on the left are always joined inside; so are the two on the right. Pressing the cap joins the left pair to the right pair. That is why you use two legs that are diagonal (or on opposite sides).</p></div>
    <div><div class="kv"><span>Wiring</span><b>pin ─ button ─ GND, with INPUT_PULLUP</b><span>The pin reads</span><b class="pbRead"></b></div><svg class="flowsvg pbTr" viewBox="0 0 320 120" role="img" aria-label="Signal on the pin while the button is pressed"></svg><div class="controls"><label class="chk"><input type="checkbox" class="pbDeb"><span>Ignore changes for 30 ms (debounce)</span></label></div><div class="ix-out pbO">Press the button a few times.</div></div></div>`);
  const draw = () => { $(".pbSvg", el).innerHTML = `<rect x="70" y="50" width="180" height="150" rx="14" fill="#E5E7EB" stroke="#6B7280" stroke-width="3"/><circle cx="160" cy="125" r="${down ? 38 : 44}" fill="${down ? "#4F46E5" : "#6366F1"}" stroke="#312E81" stroke-width="4"/>
     ${[[70, 70], [70, 180], [250, 70], [250, 180]].map((p, i) => `<path d="M${p[0]} ${p[1]} h${i < 2 ? -30 : 30}" stroke="#9CA3AF" stroke-width="8" stroke-linecap="round"/>`).join("")}
     <path d="M70 70 V180" stroke="#F59E0B" stroke-width="5" stroke-dasharray="${1}"/><path d="M250 70 V180" stroke="#F59E0B" stroke-width="5"/><path d="M70 125 H250" stroke="${down ? "#16A34A" : "#CBD5E1"}" stroke-width="${down ? 7 : 3}" stroke-dasharray="${down ? 0 : "6 6"}"/>
     <text x="160" y="30" text-anchor="middle" style="font-size:12px">${down ? "PRESSED: left pair and right pair are connected" : "not pressed: the pairs are separate"}</text><text x="36" y="60" style="font-size:11px">1</text><text x="36" y="196" style="font-size:11px">2</text><text x="288" y="60" style="font-size:11px">3</text><text x="288" y="196" style="font-size:11px">4</text><text x="160" y="226" text-anchor="middle" style="font-size:11px;fill:#92400E">1–2 always joined · 3–4 always joined</text>`;
    $(".pbRead", el).innerHTML = down ? "<b>LOW</b> (pressed: pin connects to GND)" : "<b>HIGH</b> (not pressed: pull-up holds it high)"; };
  const bounce = () => { const edges = [0]; let t = 0; const n = 2 + Math.floor(Math.random() * 4) * 2; for (let i = 0; i < n; i++){ t += 0.3 + Math.random() * 1.1; edges.push(t); } return edges; };
  const press = () => { const e = bounce(), settle = e[e.length - 1]; const raw = e.length; const counted = deb ? 1 : Math.ceil(raw / 2); presses.push(counted); const W = 320, X = t => 20 + t / (settle + 3) * 280; let h = `<path d="M20 20 H${X(0)}`; let lvl = 1; e.forEach(t => { h += ` V${lvl ? 100 : 20} H${X(t)}`; lvl = lvl ? 0 : 1; }); h += ` V${lvl ? 20 : 100} H300" stroke="#4F46E5" stroke-width="2.5" fill="none"/>`;
    $(".pbTr", el).innerHTML = `${h}<text x="22" y="14" style="font-size:10px">HIGH</text><text x="22" y="116" style="font-size:10px">LOW</text><text x="170" y="60" style="font-size:11px;fill:#B91C1C">chatter: ${raw} edges in ${settle.toFixed(1)} ms</text>`;
    $(".pbO", el).innerHTML = deb ? `<b>Debounced:</b> the first edge counts and the next 30 ms are ignored, so this press counts <b>once</b>. ✓` : `<b>Not debounced:</b> the contacts bounced ${raw} times, so a sketch that counts HIGH→LOW edges would count <b>${counted}</b> press${counted > 1 ? "es" : ""} for one push.`; markAct("partButton", "used"); };
  const B = $(".pbBtn", el); B.onpointerdown = e => { e.preventDefault(); down = true; draw(); }; B.onpointerup = B.onpointerleave = () => { if (down){ down = false; draw(); press(); } };
  B.onkeydown = e => { if ((e.key === " " || e.key === "Enter") && !down){ e.preventDefault(); down = true; draw(); } }; B.onkeyup = e => { if (down && (e.key === " " || e.key === "Enter")){ down = false; draw(); press(); } };
  $(".pbDeb", el).onchange = e => { deb = e.target.checked; };
  $(".pbTr", el).innerHTML = `<path d="M20 20 H300" stroke="#4F46E5" stroke-width="2.5" fill="none"/><text x="22" y="14" style="font-size:10px">HIGH</text><text x="22" y="116" style="font-size:10px">LOW</text><text x="60" y="70" style="font-size:12px">press the button to see the signal on the pin</text>`; draw();
};
INTERACTIVES.partBuzzer = function(el){
  let f = 440, active = false, ctx = null;
  const NAMES = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"], note = hz => { const n = Math.round(12 * Math.log2(hz / 440)) + 69; return NAMES[((n % 12) + 12) % 12] + (Math.floor(n / 12) - 1); };
  el.innerHTML = bench("Inside a piezo buzzer: vibration makes sound", `<div class="ix-grid2"><div><svg class="partsvg" viewBox="0 0 320 240" role="img" aria-label="Piezo disc flexing back and forth"><g class="pzG"><ellipse class="pzDisc" cx="160" cy="120" rx="110" ry="14" fill="#FBBF24" stroke="#92400E" stroke-width="3"/><ellipse class="pzCer" cx="160" cy="116" rx="70" ry="8" fill="#F8FAFC" stroke="#64748B"/></g>
     <path d="M30 190 H120 M200 190 H290" stroke="#64748B" stroke-width="3"/><text x="160" y="214" text-anchor="middle" style="font-size:12px">metal disc + ceramic layer; two wires</text><g class="pzWaves" fill="none" stroke="#4F46E5" stroke-width="3"></g></svg>
     <p class="explain">A <b>passive</b> piezo is a disc that <b>bends</b> each time the voltage flips. Flip it 440 times a second and the air vibrates 440 times a second: you hear the note A.</p></div>
    <div><div class="seg seg-sm pzT"><button type="button" data-a="0" aria-selected="true">Passive buzzer</button><button type="button" data-a="1" aria-selected="false">Active buzzer</button></div>
     <div class="controls pzCtl"><label>Frequency <input type="range" class="pzF" min="100" max="2000" step="1" value="${f}"></label><span class="rangeval pzFv"></span></div>
     <div class="controls"><button class="btn primary pzPlay" type="button">▶ Hear it</button></div><div class="codebox"><pre class="code"><code class="pzCode"></code></pre></div><div class="ix-out pzO"></div></div></div>`);
  const draw = () => { f = +$(".pzF", el).value; $(".pzFv", el).textContent = active ? "fixed" : f + " Hz · " + note(f); $(".pzCtl", el).style.opacity = active ? .4 : 1; $(".pzF", el).disabled = active;
    $(".pzCode", el).textContent = active ? "digitalWrite(BUZZER_PIN, HIGH);  // beeps\ndelay(200);\ndigitalWrite(BUZZER_PIN, LOW);   // silent" : `tone(BUZZER_PIN, ${f});   // play ${note(f)}\ndelay(500);\nnoTone(BUZZER_PIN);       // stop`;
    $(".pzO", el).innerHTML = active ? "<b>Active buzzer:</b> it has its own tiny oscillator inside, so <i>any</i> power makes the same fixed beep. You can only switch it on and off, not choose the pitch." : `<b>${f} Hz</b> = the note <b>${note(f)}</b>. Higher frequency, higher pitch. Doubling the frequency raises the note by one octave (220 → 440 → 880).`; markAct("partBuzzer", "used"); };
  let ph = 0; const rate = () => active ? 3 : 0.5 + f / 2000 * 6;
  aLoop(el, dt => { ph += dt / 1000 * rate() * Math.PI * 2; const a = Math.sin(ph), disc = $(".pzDisc", el); if (!disc) return; disc.setAttribute("cy", 120 + a * 16); $(".pzCer", el).setAttribute("cy", 116 + a * 16); $(".pzWaves", el).innerHTML = [0, 1, 2].map(k => `<path d="M${130 - k * 14} ${70 - k * 14} q${30 + k * 14} ${-10 - k * 5} ${60 + k * 28} 0" opacity="${.7 - k * .2 + a * .25}"/>`).join(""); });
  const play = () => { try { ctx = ctx || new (window.AudioContext || window.webkitAudioContext)(); const o = ctx.createOscillator(), g = ctx.createGain(); o.type = "square"; o.frequency.value = active ? 2300 : f; g.gain.value = .06; o.connect(g); g.connect(ctx.destination); o.start(); o.stop(ctx.currentTime + .4); } catch (e) { $(".pzO", el).innerHTML += " (Your browser blocked sound.)"; } };
  $(".pzF", el).oninput = draw; $(".pzPlay", el).onclick = play; el.querySelectorAll(".pzT button").forEach(b => b.onclick = () => { active = b.dataset.a === "1"; el.querySelectorAll(".pzT button").forEach(x => x.setAttribute("aria-selected", x === b)); draw(); }); draw();
};

/* ---------- 1.5 PWM: dim light from fast on/off ---------- */
INTERACTIVES.pwmViz = function(el){
  el.innerHTML = bench("PWM: dim light from fast on/off switching", `<div class="controls"><label>analogWrite value <input type="range" class="pwV" min="0" max="255" value="64"></label><span class="rangeval pwVv"></span></div>
   <div class="ix-grid2"><div><svg class="flowsvg pwSvg" viewBox="0 0 400 160" role="img" aria-label="Square wave on the pin: the share of time it is high is the duty cycle"></svg><p class="explain">The pin switches on and off many times a second. The coloured part is the time the pin is ON.</p></div>
   <div><div class="big-led pwL" style="margin:6px auto" role="img" aria-label="LED brightness"></div><div class="ix-out pwO"></div></div></div>`);
  const draw = () => { const v = +$(".pwV", el).value, d = v / 255, V = BOARDS[getBoard()].logic, per = 80, H = 30, Lo = 112, avgY = Lo - d * (Lo - H);
    let h = `<path d="M10 ${Lo} H390" stroke="#94A3B8" stroke-dasharray="3 3"/><text x="4" y="${H - 8}" class="svgtxt">${V} V</text><text x="4" y="${Lo + 16}" class="svgtxt">0 V</text>`;
    for (let k = 0; k < 4; k++){ const x0 = 30 + k * per, w = per * d; if (w > 0) h += `<rect x="${x0}" y="${H}" width="${w}" height="${Lo - H}" fill="#F59E0B" opacity=".45"/>`; h += `<path d="M${x0} ${Lo} V${w > 0 ? H : Lo} H${x0 + w} V${Lo} H${x0 + per}" fill="none" stroke="#B45309" stroke-width="3"/>`; }
    h += `<path d="M30 ${avgY} H350" stroke="#4F46E5" stroke-width="2.5" stroke-dasharray="6 4"/><text x="354" y="${avgY + 4}" class="svgtxt b" fill="#4338CA">average</text>`;
    $(".pwSvg", el).innerHTML = h; const L = $(".pwL", el), g = d; L.style.background = `rgb(${Math.round(127 + 121 * g)},${Math.round(29 + 84 * g)},${Math.round(29 + 84 * g)})`; L.style.boxShadow = d > .05 ? `0 0 ${8 + g * 26}px ${g * 12}px rgba(248,113,113,${.15 + g * .65})` : "none";
    $(".pwO", el).innerHTML = `<div class="bigcalc"><code>analogWrite(pin, ${v})</code></div>Duty cycle = ${v} ÷ 255 = <b>${(d * 100).toFixed(0)} %</b>. The average voltage is ${(d * 100).toFixed(0)} % of ${V} V = <b>${(d * V).toFixed(2)} V</b>, even though the pin only outputs 0 V or ${V} V. Your eye sees the average, so the LED looks about ${(d * 100).toFixed(0)} % as bright.`; $(".pwVv", el).textContent = v + " (" + (d * 100).toFixed(0) + " %)"; markAct("pwmViz", "used"); };
  $(".pwV", el).oninput = draw; draw();
};
